actions.script:
const out = ec.service.sync().name('org.moqui.impl.CallServices.start#Call').parameters({calleeUserIdList: calleeUserIdList ? (Array.isArray(calleeUserIdList) ? calleeUserIdList : String(calleeUserIdList).split(',')) : null,
    chatRoomId: chatRoomId || null, video: String(video) !== 'false', idempotencyKey: idempotencyKey || null,
    requireE2ee: typeof requireE2ee !== 'undefined' && String(requireE2ee) === 'true', cryptoDeviceId: (typeof cryptoDeviceId !== 'undefined' && cryptoDeviceId) || null, scriptTransform: typeof scriptTransform !== 'undefined' && scriptTransform != null && scriptTransform !== '' ? String(scriptTransform) === 'true' : null}).requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse(Object.assign({reasonCode: out.reasonCode || null, errors}, {callSessionId: out.callSessionId || null, callLegId: out.callLegId || null, call: out.call || null}))

const out = ec.service.sync().name('org.moqui.impl.CallServices.register#CallDevice').parameters({callSessionId: callSessionId || '',
    callLegId: (typeof callLegId !== 'undefined' && callLegId) || null, cryptoDeviceId: (typeof cryptoDeviceId !== 'undefined' && cryptoDeviceId) || null, scriptTransform: typeof scriptTransform !== 'undefined' && scriptTransform != null && scriptTransform !== '' ? String(scriptTransform) === 'true' : null}).requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse(Object.assign({reasonCode: out.reasonCode || null, errors}, {callLegId: out.callLegId || null, call: out.call || null}))

const out = ec.service.sync().name('org.moqui.impl.CallServices.create#CallLink').parameters({name: name || '', chatRoomId: chatRoomId || null, policy: policy === 'link' ? 'link' : 'lobby',
    video: String(video) !== 'false', expiryHours: expiryHours ? Number(expiryHours) : null,
    requireE2ee: typeof requireE2ee !== 'undefined' && String(requireE2ee) === 'true'}).requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse(Object.assign({reasonCode: out.reasonCode || null, errors}, {callLinkId: out.callLinkId || null, path: out.path || null}))

const out = ec.service.sync().name('org.moqui.impl.VoiceServices.send#PhoneDtmf').parameters({callSessionId: callSessionId || '', digits: digits || ''})
    .requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, sent: !!out.sent})

const out = ec.service.sync().name('org.moqui.impl.VoiceServices.hold#PhoneCall').parameters({callSessionId: callSessionId || ''})
    .requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, call: null})

const out = ec.service.sync().name('org.moqui.impl.VoiceServices.resume#PhoneCall').parameters({callSessionId: callSessionId || ''})
    .requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, call: null})

const out = ec.service.sync().name('org.moqui.impl.CallTransferServices.transfer#Call').parameters({callSessionId: callSessionId || '', targetType: targetType || '', targetId: targetId || null, mode: mode || 'blind', revision: revision ? Number(revision) : null})
    .requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, callTransferId: out.callTransferId || null, call: out.call || null})

const out = ec.service.sync().name('org.moqui.impl.CallTransferServices.complete#CallTransfer').parameters({callTransferId: callTransferId || ''})
    .requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, call: out.call || null})

const out = ec.service.sync().name('org.moqui.impl.CallTransferServices.cancel#CallTransfer').parameters({callTransferId: callTransferId || ''})
    .requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, call: out.call || null})

const out = ec.service.sync().name('org.moqui.impl.CallTransferServices.add#CallParticipant').parameters({callSessionId: callSessionId || '', userId: userId || null, phoneNumber: phoneNumber || null, revision: revision ? Number(revision) : null})
    .requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, call: out.call || null})

const out = ec.service.sync().name('org.moqui.impl.CallTransferServices.merge#Calls').parameters({callSessionId: callSessionId || '', otherCallSessionId: otherCallSessionId || '', revision: revision ? Number(revision) : null})
    .requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, movedCount: out.movedCount || 0, call: out.call || null})

const out = ec.service.sync().name('org.moqui.impl.CallTransferServices.convert#CallToMeeting').parameters({callSessionId: callSessionId || '', revision: revision ? Number(revision) : null})
    .requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, call: out.call || null})

const out = ec.service.sync().name('org.moqui.impl.CallServices.get#CallContext').parameters({callSessionId: callSessionId || ''})
    .requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, number: out.number || null, contactList: out.contactList || [], recordList: out.recordList || [], failedParts: out.failedParts || [], unavailable: !!out.unavailable})

const out = ec.service.sync().name('org.moqui.impl.CallQueueServices.find#TransferQueues').parameters({term: term || ''})
    .requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, queueList: out.queueList || []})

const out = ec.service.sync().name('org.moqui.impl.CallServices.get#IceServers').parameter('callSessionId', callSessionId || '')
    .requireNewTransaction(true).disableAuthz().call() || {}
ec.message.clearErrors()
ec.web.sendJsonResponse({iceServers: out.iceServers || []})

const out = ec.service.sync().name('org.moqui.impl.CallRecordingServices.start#Recording').parameters({callSessionId: callSessionId || '',
    kind: kind === 'mixed' ? 'mixed' : 'perTrack'}).requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, recording: out.recording || null})

const out = ec.service.sync().name('org.moqui.impl.CallRecordingServices.stop#Recording').parameters({callSessionId: callSessionId || '',
    callRecordingId: callRecordingId || null}).requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, recording: out.recording || null})

const out = ec.service.sync().name('org.moqui.impl.CallRecordingServices.pause#Recording').parameters({callSessionId: callSessionId || '',
    callRecordingId: callRecordingId || null}).requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, recording: out.recording || null})

const out = ec.service.sync().name('org.moqui.impl.CallRecordingServices.resume#Recording').parameters({callSessionId: callSessionId || '',
    callRecordingId: callRecordingId || null}).requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, recording: out.recording || null})

const out = ec.service.sync().name('org.moqui.impl.CallRecordingServices.ack#RecordingNotice').parameters({callSessionId: callSessionId || ''})
    .requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, recording: out.recording || null})

const out = ec.service.sync().name('org.moqui.impl.CallRecordingServices.withdraw#RecordingConsent').parameters({callSessionId: callSessionId || ''})
    .requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, recording: out.recording || null})

const out = ec.service.sync().name('org.moqui.impl.CallCaptionServices.get#CaptionState').parameter('callSessionId', callSessionId || '')
    .requireNewTransaction(true).disableAuthz().call() || {}
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, captions: out.captions || {allowed: false, on: false}})
